// === Zaptec configuratie ===
// Stel bij voorkeur OS-omgevingsvariabelen in op de GX (aanbevolen).
// Anders kun je de standaardwaarden hieronder aanpassen.
const cfg = {
    baseUrl: env.get('ZAPTEC_BASE_URL') || 'https://api.zaptec.com',
    username: env.get('ZAPTEC_USERNAME') || 'VUL_IN@voorbeeld.nl',
    password: env.get('ZAPTEC_PASSWORD') || 'VUL_WACHTWOORD_IN',
    chargerId: env.get('ZAPTEC_CHARGER_ID') || 'VUL_CHARGER_GUID_IN'
};
flow.set('zaptecCfg', cfg);

const token = flow.get('zaptecToken');
const expiry = flow.get('zaptecTokenExpiry') || 0;

// Hergebruik een geldig token (met 60s marge) om onnodige logins te voorkomen.
if (token && Date.now() < (expiry - 60000)) {
    msg.access_token = token;
    node.status({ fill: 'green', shape: 'dot', text: 'token ok' });
    return [null, msg];
}

// Nieuw token nodig via OAuth2 password grant (ROPC).
msg.method = 'POST';
msg.url = cfg.baseUrl + '/oauth/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'grant_type=password'
    + '&username=' + encodeURIComponent(cfg.username)
    + '&password=' + encodeURIComponent(cfg.password)
    + '&scope=openid';
node.status({ fill: 'blue', shape: 'ring', text: 'token ophalen...' });
return [msg, null];

const body = msg.payload || {};
if (!body.access_token) {
    node.status({ fill: 'red', shape: 'dot', text: 'auth mislukt' });
    node.error('Zaptec: geen access_token ontvangen. Controleer gebruikersnaam/wachtwoord.', msg);
    return null;
}
flow.set('zaptecToken', body.access_token);
const ttlMs = (Number(body.expires_in) || 3600) * 1000;
flow.set('zaptecTokenExpiry', Date.now() + ttlMs);
msg.access_token = body.access_token;
node.status({ fill: 'green', shape: 'dot', text: 'token vernieuwd' });
return msg;

const cfg = flow.get('zaptecCfg') || {};
const token = msg.access_token || flow.get('zaptecToken');
if (!token) {
    node.error('Geen Zaptec-token beschikbaar.', msg);
    return null;
}
if (!cfg.chargerId || /VUL_/.test(cfg.chargerId)) {
    node.status({ fill: 'red', shape: 'dot', text: 'charger-id ontbreekt' });
    node.error('ZAPTEC_CHARGER_ID is niet ingesteld. Zoek de GUID op via het tabblad "Zaptec - chargers opzoeken".', msg);
    return null;
}
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + token };
msg.url = cfg.baseUrl + '/api/chargers/' + encodeURIComponent(cfg.chargerId) + '/state';
delete msg.payload;
return msg;

// Zet Zaptec state-observaties om naar payload voor een Victron energiemeter (rol: EV charger).
const obs = Array.isArray(msg.payload)
    ? msg.payload
    : (msg.payload && Array.isArray(msg.payload.Data) ? msg.payload.Data : []);
if (!obs.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen state ontvangen' });
    return null;
}

// Observaties indexeren op StateId.
const s = {};
for (const o of obs) {
    if (o && o.StateId !== undefined && o.StateId !== null) {
        s[o.StateId] = o.ValueAsString;
    }
}

const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const r = (v, d) => { const f = Math.pow(10, d === undefined ? 0 : d); return Math.round((v || 0) * f) / f; };

// Zaptec observatie-ID's (zie https://api.zaptec.com/api/constants).
const v1 = num(s[501]), v2 = num(s[502]), v3 = num(s[503]); // Voltage L1/L2/L3 (V)
const i1 = num(s[507]), i2 = num(s[508]), i3 = num(s[509]); // Current L1/L2/L3 (A)
let pTotal = num(s[513]);                                    // TotalChargePower (W)

// Vermogen per fase (schijnbaar vermogen V*I; EV-laden benadert cos phi = 1).
const p1 = v1 * i1, p2 = v2 * i2, p3 = v3 * i3;
const pSum = p1 + p2 + p3;
if (!pTotal) pTotal = pSum;

// Online-status (IsOnline = observatie -2). Als afwezig: aannemen online.
let online = 1;
if (s[-2] !== undefined) online = (s[-2] === '1' || s[-2] === 1) ? 1 : 0;

// Totale (levensduur) energie in kWh voor /Ac/Energy/Forward.
let ef = flow.get('zaptecEnergyForward');
if (typeof ef !== 'number' || isNaN(ef)) ef = 0;
const nowMs = Date.now();
const lastMs = flow.get('zaptecEnergyTs') || nowMs;

// Probeer de officiele gesigneerde meterstand (OCMF, observatie 554) te lezen.
function parseOcmfKwh(str) {
    if (!str || typeof str !== 'string' || str.indexOf('OCMF') === -1) return null;
    try {
        const parts = str.split('|');
        for (const p of parts) {
            const t = p.trim();
            if (t.charAt(0) === '{' && t.indexOf('"RD"') !== -1) {
                const j = JSON.parse(t);
                if (Array.isArray(j.RD) && j.RD.length) {
                    const last = j.RD[j.RD.length - 1];
                    if (last && last.RV !== undefined && last.RV !== null) {
                        const val = parseFloat(last.RV);
                        if (!isNaN(val)) return val;
                    }
                }
            }
        }
    } catch (e) { /* negeren, val terug op integratie */ }
    return null;
}

const ocmf = parseOcmfKwh(s[554]);
if (ocmf !== null && ocmf >= ef) {
    ef = ocmf; // gebruik de officiele meterstand indien beschikbaar
} else {
    // Terugval: integreer vermogen over tijd. Guard voorkomt sprongen na downtime.
    const dtH = (nowMs - lastMs) / 3600000;
    if (dtH > 0 && dtH < 1) ef += (pTotal * dtH) / 1000;
}
flow.set('zaptecEnergyForward', ef);
flow.set('zaptecEnergyTs', nowMs);

// Positie in het Victron-systeem: 0 = AC-uit, 1 = AC-in 1, 2 = AC-in 2 (standaard AC-in 1).
const position = parseInt(env.get('ZAPTEC_METER_POSITION'), 10);
msg.payload = {
    Connected: online,
    Position: isNaN(position) ? 1 : position,
    'Ac/Power': r(pTotal, 1),
    'Ac/Energy/Forward': r(ef, 3),
    'Ac/L1/Voltage': r(v1, 1),
    'Ac/L1/Current': r(i1, 2),
    'Ac/L1/Power': r(p1, 1),
    'Ac/L2/Voltage': r(v2, 1),
    'Ac/L2/Current': r(i2, 2),
    'Ac/L2/Power': r(p2, 1),
    'Ac/L3/Voltage': r(v3, 1),
    'Ac/L3/Current': r(i3, 2),
    'Ac/L3/Power': r(p3, 1)
};

node.status({ fill: online ? 'green' : 'grey', shape: 'dot', text: r(pTotal, 0) + ' W | ' + r(ef, 2) + ' kWh' });
return msg;

// Bouwt een VOLLEDIGE Victron EV-charger payload voor de driver 'dbus-mqtt-ev-charger'.
// Zo verschijnen laadstroom, sessie-energie, sessie-tijd en status op de EV-charger-pagina.
// Vereist: driver geinstalleerd op Venus OS die luistert op het topic hieronder.
const obs = Array.isArray(msg.payload)
    ? msg.payload
    : (msg.payload && Array.isArray(msg.payload.Data) ? msg.payload.Data : []);
if (!obs.length) { return null; }

const s = {};
for (const o of obs) {
    if (o && o.StateId !== undefined && o.StateId !== null) s[o.StateId] = o.ValueAsString;
}
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const r = (v, d) => { const f = Math.pow(10, d === undefined ? 0 : d); return Math.round((v || 0) * f) / f; };

const v1 = num(s[501]), v2 = num(s[502]), v3 = num(s[503]);
const i1 = num(s[507]), i2 = num(s[508]), i3 = num(s[509]);
let pTotal = num(s[513]);
const p1 = v1 * i1, p2 = v2 * i2, p3 = v3 * i3;
if (!pTotal) pTotal = p1 + p2 + p3;

// Laadstroom (A): hoogste fasestroom (fasen zijn doorgaans gelijk).
const current = Math.max(i1, i2, i3);

// Totale energie (kWh): hergebruik dezelfde teller als node 4 (OCMF/integratie).
let ef = flow.get('zaptecEnergyForward');
if (typeof ef !== 'number' || isNaN(ef)) ef = 0;

// Sessie-energie (kWh) uit Zaptec observatie 553.
const sessionEnergy = num(s[553]);

// Online + status uit ChargerOperationMode (710).
let online = 1;
if (s[-2] !== undefined) online = (s[-2] === '1' || s[-2] === 1) ? 1 : 0;
const mode = parseInt(s[710], 10);
let status = 0; // 0=Disconnected, 1=Connected, 2=Charging, 3=Charged
if (mode === 2) status = 1;
else if (mode === 3) status = 2;
else if (mode === 5) status = 3;

// Sessie-laadtijd (s): bijhouden vanaf het moment dat laden start.
const nowMs = Date.now();
const sessId = s[721] || '';
let sess = flow.get('zaptecSession') || {};
let chargingTime = 0;
if (status === 2) {
    if (sess.id !== sessId || !sess.start) sess = { id: sessId, start: nowMs, last: nowMs };
    sess.last = nowMs;
    chargingTime = Math.round((nowMs - sess.start) / 1000);
} else if (status === 3 && sess.id === sessId && sess.start) {
    chargingTime = Math.round(((sess.last || nowMs) - sess.start) / 1000);
} else if (status === 0) {
    sess = {};
}
flow.set('zaptecSession', sess);

// Optioneel: ingestelde/max laadstroom (observatie 708 ChargeCurrentSet).
const setCurrent = num(s[708]);

msg.payload = {
    Ac: {
        Power: r(pTotal, 1),
        L1: { Power: r(p1, 1) },
        L2: { Power: r(p2, 1) },
        L3: { Power: r(p3, 1) },
        Energy: { Forward: r(ef, 3) }
    },
    Current: r(current, 2),
    Status: status,
    Connected: online,
    ChargingTime: chargingTime,
    Session: { Time: chargingTime, Energy: r(sessionEnergy, 3) }
};
if (setCurrent > 0) {
    msg.payload.SetCurrent = r(setCurrent, 0);
    msg.payload.MaxCurrent = r(setCurrent, 0);
}

msg.topic = env.get('ZAPTEC_EVCHARGER_TOPIC') || 'custom/ev-charger';
node.status({ fill: status >= 2 ? 'green' : 'grey', shape: 'dot', text: 'status ' + status + ' | ' + r(current, 1) + ' A | ' + r(sessionEnergy, 2) + ' kWh' });
return msg;

const cfg = {
    baseUrl: env.get('ZAPTEC_BASE_URL') || 'https://api.zaptec.com',
    username: env.get('ZAPTEC_USERNAME') || 'VUL_IN@voorbeeld.nl',
    password: env.get('ZAPTEC_PASSWORD') || 'VUL_WACHTWOORD_IN'
};
flow.set('zaptecCfg', cfg);
msg.method = 'POST';
msg.url = cfg.baseUrl + '/oauth/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'grant_type=password'
    + '&username=' + encodeURIComponent(cfg.username)
    + '&password=' + encodeURIComponent(cfg.password)
    + '&scope=openid';
return msg;

const cfg = flow.get('zaptecCfg') || { baseUrl: 'https://api.zaptec.com' };
const body = msg.payload || {};
if (!body.access_token) {
    node.error('Auth mislukt: controleer gebruikersnaam/wachtwoord.', msg);
    return null;
}
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + body.access_token };
msg.url = cfg.baseUrl + '/api/chargers';
delete msg.payload;
return msg;

const data = (msg.payload && Array.isArray(msg.payload.Data)) ? msg.payload.Data : [];
msg.payload = data.map(c => ({
    Id: c.Id,
    DeviceId: c.DeviceId,
    Name: c.Name,
    InstallationName: c.InstallationName,
    IsOnline: c.IsOnline
}));
node.status({ fill: 'green', shape: 'dot', text: data.length + ' charger(s)' });
return msg;
